"""Edge-case tests for interactive-pipeline — generated by bug-hunter agent.

Focus: annotation primitive routing through chart.__add__, interactive scene
rendering, SVG rendering, clone preservation, composition interactions, and
degenerate inputs.
"""

from __future__ import annotations

import json

import polars as pl
import pytest

import ferrum as fr
from ferrum._interactive import _render_scene
from ferrum.annotation.container import Annotate


def _scene(chart):
    """Return parsed scene dict from the interactive pipeline."""
    scene_json, packed = _render_scene(chart)
    return json.loads(scene_json), packed


def _base_chart():
    """Simple 3-row scatter for composition tests."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    return fr.Chart(df).mark_point().encode(x="x", y="y")


# ============================================================================
# 1. chart + annotate_hline: exactly 1 annotation, 0 duplicate rule marks
# ============================================================================


def test_hline_produces_exactly_one_annotation():
    """chart + annotate_hline must yield exactly 1 annotation in the scene."""
    chart = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    scene, _ = _scene(chart)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) == 1, (
        f"Expected exactly 1 annotation from annotate_hline, got {len(annotations)}"
    )


def test_hline_does_not_duplicate_rule_mark_in_layers():
    """chart + annotate_hline must NOT produce an extra rule mark batch.

    The __add__ early guard skips the RHS mark layers when the RHS has
    _annotation_primitive. If it fails, we get a duplicate rule mark batch
    alongside the annotation.
    """
    chart = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    scene, _ = _scene(chart)
    mark_kinds = [batch["kind"] for batch in scene["panels"][0].get("marks", [])]
    rule_count = mark_kinds.count("Rule") + mark_kinds.count("rule")
    assert rule_count == 0, (
        f"annotate_hline should not produce a separate Rule mark batch; "
        f"found mark kinds: {mark_kinds}"
    )


def test_hline_annotation_has_correct_type():
    """The annotation node from annotate_hline must have type='line'."""
    chart = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    scene, _ = _scene(chart)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) >= 1
    assert annotations[0].get("type") == "line", (
        f"Expected annotation type 'line', got {annotations[0].get('type')}"
    )


def test_hline_preserves_stroke_color_in_annotation():
    """annotate_hline(stroke='red') must produce an annotation with red color in style."""
    chart = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    scene, _ = _scene(chart)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) >= 1
    # Scene format: style.color is {r, g, b, a}
    color = annotations[0].get("style", {}).get("color", {})
    assert color.get("r") == 255 and color.get("g") == 0 and color.get("b") == 0, (
        f"Expected red color, got {color}"
    )


def test_hline_preserves_dash_in_annotation():
    """annotate_hline(stroke_dash=[4,4]) must produce annotation with dash in style."""
    chart = _base_chart() + fr.annotate_hline(y=3.0, stroke_dash=[4, 4])
    scene, _ = _scene(chart)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) >= 1
    # Scene format: style.dash is the dash array
    dash = annotations[0].get("style", {}).get("dash")
    assert dash == [4.0, 4.0], f"Expected dash=[4.0, 4.0], got {dash}"


# ============================================================================
# 2. chart + vline + text + rect: exactly 3 annotations
# ============================================================================


def test_three_different_annotations_produce_exactly_three():
    """chart + annotate_vline + annotate_text + annotate_rect must yield 3 annotations."""
    chart = (
        _base_chart()
        + fr.annotate_vline(x=2.0, stroke="blue")
        + fr.annotate_text(x=2.0, y=4.0, text="peak")
        + fr.annotate_rect(x1=1.0, x2=3.0, y1=2.0, y2=6.0, fill="yellow", opacity=0.2)
    )
    scene, _ = _scene(chart)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) == 3, (
        f"Expected exactly 3 annotations, got {len(annotations)}: {annotations}"
    )


def test_three_annotations_have_distinct_types():
    """The 3 annotations from vline+text+rect must have types line, text, rect."""
    chart = (
        _base_chart()
        + fr.annotate_vline(x=2.0, stroke="blue")
        + fr.annotate_text(x=2.0, y=4.0, text="peak")
        + fr.annotate_rect(x1=1.0, x2=3.0, y1=2.0, y2=6.0, fill="yellow")
    )
    scene, _ = _scene(chart)
    annotations = scene["panels"][0].get("annotations", [])
    types = {a.get("type") for a in annotations}
    assert "line" in types, f"Missing 'line' annotation type; got {types}"
    assert "text" in types, f"Missing 'text' annotation type; got {types}"
    assert "rect" in types, f"Missing 'rect' annotation type; got {types}"


def test_three_annotations_no_duplicate_marks():
    """chart + vline + text + rect: marks should only be from the base chart."""
    chart = (
        _base_chart()
        + fr.annotate_vline(x=2.0)
        + fr.annotate_text(x=2.0, y=4.0, text="peak")
        + fr.annotate_rect(x1=1.0, x2=3.0, y1=2.0, y2=6.0, fill="yellow")
    )
    scene, _ = _scene(chart)
    mark_kinds = [batch["kind"] for batch in scene["panels"][0].get("marks", [])]
    # The base chart is mark_point, so we should have 1 point batch, no rule/text/rect
    # from the annotation helpers (those should be in annotations, not marks).
    rule_count = sum(1 for k in mark_kinds if k.lower() in ("rule", "text", "rect"))
    assert rule_count == 0, (
        f"Annotation helpers should not inject mark batches; found: {mark_kinds}"
    )


# ============================================================================
# 3. chart + annotate_hline + regular_chart (no annotation)
# ============================================================================


def test_annotation_plus_regular_chart_layer():
    """(chart + annotate_hline) + regular_chart must have 1 annotation and 2 mark layers."""
    base = _base_chart()
    with_hline = base + fr.annotate_hline(y=3.0, stroke="red")
    df2 = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [3.0, 5.0, 7.0]})
    line_chart = fr.Chart(df2).mark_line().encode(x="x", y="y")
    combined = with_hline + line_chart
    scene, _ = _scene(combined)
    annotations = scene["panels"][0].get("annotations", [])
    marks = scene["panels"][0].get("marks", [])
    # Annotation from hline must survive
    assert len(annotations) == 1, (
        f"Expected 1 annotation after adding regular chart, got {len(annotations)}"
    )
    # Must have at least 2 mark batches (point + line)
    assert len(marks) >= 2, f"Expected >=2 mark batches after layering, got {len(marks)}"


def test_regular_chart_then_annotation():
    """regular_chart + annotate_hline must also produce 1 annotation."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    line_chart = fr.Chart(df).mark_line().encode(x="x", y="y")
    combined = line_chart + fr.annotate_hline(y=3.0, stroke="red")
    scene, _ = _scene(combined)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) == 1, f"Expected 1 annotation, got {len(annotations)}"


def test_annotation_between_two_layers():
    """chart + annotate_hline + another_chart: annotation must persist."""
    base = _base_chart()
    df2 = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [1.0, 3.0, 5.0]})
    another = fr.Chart(df2).mark_line().encode(x="x", y="y")
    combined = base + fr.annotate_hline(y=3.0) + another
    scene, _ = _scene(combined)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) == 1, (
        f"Annotation lost after adding another chart; got {len(annotations)}"
    )


