def test_two_regular_charts_layer_no_annotations():
    """chart + chart (no annotations) must produce 0 annotations."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    c1 = fr.Chart(df).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df).mark_line().encode(x="x", y="y")
    combined = c1 + c2
    scene, _ = _scene(combined)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) == 0, (
        f"Two plain charts should produce 0 annotations, got {len(annotations)}"
    )


def test_two_regular_charts_have_two_mark_batches():
    """chart + chart should have >= 2 mark batches (one per chart)."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    c1 = fr.Chart(df).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df).mark_line().encode(x="x", y="y")
    combined = c1 + c2
    scene, _ = _scene(combined)
    marks = scene["panels"][0].get("marks", [])
    assert len(marks) >= 2, f"Expected >= 2 mark batches, got {len(marks)}"


# ============================================================================
# 5. chart.clone() preserves _annotation_primitive
# ============================================================================


def test_clone_preserves_annotation_primitive():
    """Chart._clone() must preserve _annotation_primitive."""
    hline = fr.annotate_hline(y=3.0, stroke="red")
    assert hline._annotation_primitive is not None, "annotate_hline must set _annotation_primitive"
    cloned = hline._clone()
    assert cloned._annotation_primitive is not None, "_clone() must preserve _annotation_primitive"
    assert cloned._annotation_primitive is hline._annotation_primitive, (
        "_clone() must preserve the same annotation primitive object"
    )


def test_clone_preserves_annotations_list():
    """Chart._clone() must preserve the _annotations list."""
    combined = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    assert len(combined._annotations) == 1
    cloned = combined._clone()
    assert len(cloned._annotations) == 1, (
        f"_clone() must preserve _annotations list; got {len(cloned._annotations)}"
    )


def test_clone_does_not_alias_annotations_list():
    """Mutating the cloned annotations list must not affect the original."""
    combined = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    cloned = combined._clone()
    cloned._annotations.append("extra")
    assert len(combined._annotations) == 1, (
        "Mutations to cloned._annotations must not affect original"
    )


# ============================================================================
# 6. Annotations survive through composition types
# ============================================================================


def test_annotations_in_hconcat_children():
    """HConcat children with annotations must preserve them in the interactive scene."""
    c1 = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    c2 = _base_chart()
    concat = c1 | c2
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    # At least one panel should have annotations
    all_annotations = []
    for panel in scene.get("panels", []):
        all_annotations.extend(panel.get("annotations", []))
    assert len(all_annotations) >= 1, (
        f"HConcat: annotations from child chart must survive; found {len(all_annotations)}"
    )


def test_annotations_in_vconcat_children():
    """VConcat children with annotations must preserve them in the interactive scene."""
    c1 = _base_chart() + fr.annotate_vline(x=2.0, stroke="blue")
    c2 = _base_chart()
    concat = c1 & c2
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    all_annotations = []
    for panel in scene.get("panels", []):
        all_annotations.extend(panel.get("annotations", []))
    assert len(all_annotations) >= 1, (
        f"VConcat: annotations from child chart must survive; found {len(all_annotations)}"
    )


def test_annotations_in_layer_chart():
    """LayerChart with annotated member must preserve annotations."""
    c1 = _base_chart() + fr.annotate_hline(y=3.0)
    c2 = _base_chart()
    layered = fr.LayerChart(c1, c2)
    scene_json, _ = layered._render_interactive()
    scene = json.loads(scene_json)
    annotations = scene["panels"][0].get("annotations", [])
    assert len(annotations) >= 1, (
        f"LayerChart: annotations from member must survive; found {len(annotations)}"
    )


def test_hconcat_both_children_have_annotations():
    """HConcat with both children annotated must have annotations in both panels."""
    c1 = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    c2 = _base_chart() + fr.annotate_vline(x=2.0, stroke="blue")
    concat = c1 | c2
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    panels_with_annot = sum(1 for p in scene.get("panels", []) if len(p.get("annotations", [])) > 0)
    assert panels_with_annot >= 2, (
        f"Both HConcat panels should have annotations; only {panels_with_annot} do"
    )


# ============================================================================
# 7. chart + annotate_hline still produces correct SVG (not just interactive)
# ============================================================================


def test_hline_annotation_produces_valid_svg():
    """chart + annotate_hline must produce valid SVG (no NaN, no empty)."""
    chart = _base_chart() + fr.annotate_hline(y=3.0, stroke="red")
    svg = chart.show_svg()
    assert isinstance(svg, str)
    assert len(svg) > 0
    assert svg.startswith("<svg")
    assert "NaN" not in svg
    assert "Infinity" not in svg


def test_vline_annotation_produces_valid_svg():
    """chart + annotate_vline must produce valid SVG."""
    chart = _base_chart() + fr.annotate_vline(x=2.0, stroke="blue")
    svg = chart.show_svg()
    assert isinstance(svg, str)
    assert svg.startswith("<svg")
    assert "NaN" not in svg


def test_text_annotation_produces_valid_svg():
    """chart + annotate_text must produce valid SVG."""
    chart = _base_chart() + fr.annotate_text(x=2.0, y=4.0, text="peak")
    svg = chart.show_svg()
    assert isinstance(svg, str)
    assert svg.startswith("<svg")
    assert "NaN" not in svg


def test_rect_annotation_produces_valid_svg():
    """chart + annotate_rect must produce valid SVG."""
    chart = _base_chart() + fr.annotate_rect(x1=1.0, x2=3.0, y1=2.0, y2=6.0, fill="yellow")
    svg = chart.show_svg()
    assert isinstance(svg, str)
    assert svg.startswith("<svg")
    assert "NaN" not in svg


def test_abline_annotation_produces_valid_svg():
    """chart + annotate_abline must produce valid SVG."""
    chart = _base_chart() + fr.annotate_abline(slope=1.0, intercept=0.0, stroke="gray")
    svg = chart.show_svg()
    assert isinstance(svg, str)
    assert svg.startswith("<svg")
    assert "NaN" not in svg


def test_multiple_annotations_svg_no_duplicates():
    """chart + hline + vline + text: SVG must not have duplicate marks from annotations."""
    chart = (
        _base_chart()
        + fr.annotate_hline(y=3.0, stroke="red")
        + fr.annotate_vline(x=2.0, stroke="blue")
        + fr.annotate_text(x=2.0, y=4.0, text="peak")
    )
    svg = chart.show_svg()
    assert "NaN" not in svg
    # The SVG should render the base chart's marks plus annotation overlays.
    # The key invariant: no duplicate rule marks from the annotation helpers.
    assert svg.count("<circle") >= 3, "Base chart's 3 points must still appear in SVG"


